"use strict";(self.webpackChunkucl_artificial_intelligence_society=self.webpackChunkucl_artificial_intelligence_society||[]).push([[5035],{1660:e=>{e.exports=JSON.parse('{"collection":"tutorials","route":"/learn/tutorials/machine-learning/session-1-intro-to-machine-learning.md/","sourcePath":"knowledge/tutorials/machine-learning/session-1-intro-to-machine-learning.md","fileUrl":"https://github.com/UCLAIS/UCLAIS.github.io/blob/24e06da03aa538cbc002767935da6d95d724ede8/knowledge/tutorials/machine-learning/session-1-intro-to-machine-learning.md","format":"md","document":{"id":"knowledge:tutorials/machine-learning/session-1-intro-to-machine-learning.md","title":"Session 1: Intro to Machine Learning and Linear Regression","sections":[{"id":"section-1","heading":"Session 1: Intro to Machine Learning and Linear Regression","text":"Session 1 of the seven-session Machine Learning Tutorial Series. These notes cover slides 1\u201319 of `Tutorial1.pptx`, followed by the 19 ordered cells of `Tutorial1NotebookAnswers.ipynb`. The source files do not state an academic year or session date.\\n\\n[Download the answers notebook](https://uclai.co.uk/materials/tutorials/machine-learning/tutorial-1-linear-regression-answers.ipynb). Saved outputs and execution counts have been removed. The notebook was not run during publication; its teaching code is unchanged.\\n\\nThe slide illustrations are described in words here. Their source links are retained where the deck supplies them. Third-party images, animations and speaker notes are not reproduced, and the original PowerPoint is not offered as a download in this publication.","kind":"explanation","nodes":[{"type":"paragraph","children":[{"type":"text","value":"Session 1 of the seven-session Machine Learning Tutorial Series. These notes cover slides 1\u201319 of "},{"type":"inlineCode","value":"Tutorial1.pptx"},{"type":"text","value":", followed by the 19 ordered cells of "},{"type":"inlineCode","value":"Tutorial1NotebookAnswers.ipynb"},{"type":"text","value":". The source files do not state an academic year or session date."}]},{"type":"paragraph","children":[{"type":"link","href":"https://uclai.co.uk/materials/tutorials/machine-learning/tutorial-1-linear-regression-answers.ipynb","children":[{"type":"text","value":"Download the answers notebook"}]},{"type":"text","value":". Saved outputs and execution counts have been removed. The notebook was not run during publication; its teaching code is unchanged."}]},{"type":"paragraph","children":[{"type":"text","value":"The slide illustrations are described in words here. Their source links are retained where the deck supplies them. Third-party images, animations and speaker notes are not reproduced, and the original PowerPoint is not offered as a download in this publication."}]}]},{"id":"section-2","heading":"What is machine learning? (slides 1\u20132)","text":"Instead of writing a rule for every case, supply examples and fit a model to learn patterns. Data and a model provide a way to measure and improve predictions. A spam filter trained on labelled messages is the deck\'s example.","kind":"explanation","nodes":[{"type":"paragraph","children":[{"type":"text","value":"Instead of writing a rule for every case, supply examples and fit a model to learn patterns. Data and a model provide a way to measure and improve predictions. A spam filter trained on labelled messages is the deck\'s example."}]}]},{"id":"section-3","heading":"Types of learning (slides 3\u20135)","text":"- **Supervised learning:** use labelled input\u2013target examples to learn a mapping from `x` to `y`.\\n- **Unsupervised learning:** find structure in input data without supplied target labels.\\n- **Reinforcement learning:** learn actions through interaction and reward signals.\\n\\nSlide 4 contrasts clustering unlabelled points with learning a boundary between labelled classes. Slide 5 contrasts recognising a labelled cat with discovering that two unlabelled examples are similar. Most of the series focuses on supervised learning.","kind":"explanation","nodes":[{"type":"list","ordered":false,"children":[{"type":"listItem","children":[{"type":"paragraph","children":[{"type":"strong","children":[{"type":"text","value":"Supervised learning:"}]},{"type":"text","value":" use labelled input\u2013target examples to learn a mapping from "},{"type":"inlineCode","value":"x"},{"type":"text","value":" to "},{"type":"inlineCode","value":"y"},{"type":"text","value":"."}]}]},{"type":"listItem","children":[{"type":"paragraph","children":[{"type":"strong","children":[{"type":"text","value":"Unsupervised learning:"}]},{"type":"text","value":" find structure in input data without supplied target labels."}]}]},{"type":"listItem","children":[{"type":"paragraph","children":[{"type":"strong","children":[{"type":"text","value":"Reinforcement learning:"}]},{"type":"text","value":" learn actions through interaction and reward signals."}]}]}]},{"type":"paragraph","children":[{"type":"text","value":"Slide 4 contrasts clustering unlabelled points with learning a boundary between labelled classes. Slide 5 contrasts recognising a labelled cat with discovering that two unlabelled examples are similar. Most of the series focuses on supervised learning."}]}]},{"id":"section-4","heading":"A supervised learning workflow (slide 6)","text":"Collect and clean data, choose features and targets, select a model and loss, fit the model, then assess performance on held-out data.\\n\\n**Editorial clarification:** the caption under \u201cTrain\u201d on slide 6 mentions unseen data. Fitting uses training data; evaluation on held-out data is the testing step, as distinguished on slide 7 and in the notebook.","kind":"explanation","nodes":[{"type":"paragraph","children":[{"type":"text","value":"Collect and clean data, choose features and targets, select a model and loss, fit the model, then assess performance on held-out data."}]},{"type":"paragraph","children":[{"type":"strong","children":[{"type":"text","value":"Editorial clarification:"}]},{"type":"text","value":" the caption under \u201cTrain\u201d on slide 6 mentions unseen data. Fitting uses training data; evaluation on held-out data is the testing step, as distinguished on slide 7 and in the notebook."}]}]},{"id":"section-5","heading":"Generalisation and dataset splits (slide 7)","text":"The training split is used to fit parameters. The test split is held out to assess performance on unseen examples. The slide\'s diagram also includes validation data, with illustrative train/validation/test proportions of 80/10/10, 70/15/15 and 60/20/20. These are examples rather than a required split.","kind":"explanation","nodes":[{"type":"paragraph","children":[{"type":"text","value":"The training split is used to fit parameters. The test split is held out to assess performance on unseen examples. The slide\'s diagram also includes validation data, with illustrative train/validation/test proportions of 80/10/10, 70/15/15 and 60/20/20. These are examples rather than a required split."}]}]},{"id":"section-6","heading":"Linear regression: fitting a line (slides 8\u201312)","text":"The aim is to predict a continuous number by fitting a line to input\u2013target pairs. Slides 9\u201311 show the same upward-trending scatter plot: first the data, then a flat prediction at 10, then a sloping fitted line. The question is how to choose a line that fits the observations.","kind":"explanation","nodes":[{"type":"paragraph","children":[{"type":"text","value":"The aim is to predict a continuous number by fitting a line to input\u2013target pairs. Slides 9\u201311 show the same upward-trending scatter plot: first the data, then a flat prediction at 10, then a sloping fitted line. The question is how to choose a line that fits the observations."}]}]},{"id":"section-7","heading":"Predictions, weights and intercepts (slide 13)","text":"For one feature, the prediction is `\u0177 = wx + b`. The weight `w` controls the slope and the intercept `b` controls the baseline. With several features, `\u0177 = w\u2081x\u2081 + w\u2082x\u2082 + \u2026 + w_d x_d + b = w\u1d40x + b`.","kind":"explanation","nodes":[{"type":"paragraph","children":[{"type":"text","value":"For one feature, the prediction is "},{"type":"inlineCode","value":"\u0177 = wx + b"},{"type":"text","value":". The weight "},{"type":"inlineCode","value":"w"},{"type":"text","value":" controls the slope and the intercept "},{"type":"inlineCode","value":"b"},{"type":"text","value":" controls the baseline. With several features, "},{"type":"inlineCode","value":"\u0177 = w\u2081x\u2081 + w\u2082x\u2082 + \u2026 + w_d x_d + b = w\u1d40x + b"},{"type":"text","value":"."}]}]},{"id":"section-8","heading":"Least squares and residuals (slide 14)","text":"A residual is `e\u1d62 = y\u1d62 \u2212 \u0177\u1d62`, the observed value minus its prediction. Squaring prevents positive and negative residuals from cancelling and gives large errors more weight. The slide and notebook define the loss as half the mean squared residual:\\n\\n`L(w,b) = (1 / (2n)) \u03a3\u1d62\u208c\u2081\u207f (y\u1d62 \u2212 \u0177\u1d62)\xb2`.","kind":"explanation","nodes":[{"type":"paragraph","children":[{"type":"text","value":"A residual is "},{"type":"inlineCode","value":"e\u1d62 = y\u1d62 \u2212 \u0177\u1d62"},{"type":"text","value":", the observed value minus its prediction. Squaring prevents positive and negative residuals from cancelling and gives large errors more weight. The slide and notebook define the loss as half the mean squared residual:"}]},{"type":"paragraph","children":[{"type":"inlineCode","value":"L(w,b) = (1 / (2n)) \u03a3\u1d62\u208c\u2081\u207f (y\u1d62 \u2212 \u0177\u1d62)\xb2"},{"type":"text","value":"."}]}]},{"id":"section-9","heading":"Two approaches to fitting parameters (slides 15\u201318)","text":"The normal-equation approach finds a least-squares solution directly. The deck writes `w = (X\u1d40X)\u207b\xb9X\u1d40y`; in the notebook the parameter vector includes both slope and intercept. The notebook uses `np.linalg.solve` rather than explicitly computing an inverse.\\n\\nGradient descent instead repeatedly moves parameters opposite to the gradient: `w \u2190 w \u2212 \u03b7 \u2202L/\u2202w` and `b \u2190 b \u2212 \u03b7 \u2202L/\u2202b`. The learning rate `\u03b7` sets the step size. For this linear least-squares problem, the loss is convex, which motivates the bowl analogy on slide 16.\\n\\n**Editorial qualifications:** the inverse formula requires `X\u1d40X` to be invertible. The slide 18 surface is a generic non-convex illustration; it should not be taken as the shape of this linear least-squares loss. Claims on slide 18 about a single-step solution and scaling describe the two approaches broadly, rather than guaranteeing numerical stability or convergence for every dataset.\\n\\nSlide 17 credits its gradient-descent illustrations to [GeeksforGeeks](https://www.geeksforgeeks.org/machine-learning/what-is-gradient-descent/) and [Data Science Wizards on Medium](https://medium.com/@datasciencewizards/a-simple-guide-to-gradient-descent-algorithm-60cbb66a0df9). Those links are attributions supplied by the deck; their bodies are not imported here.","kind":"explanation","nodes":[{"type":"paragraph","children":[{"type":"text","value":"The normal-equation approach finds a least-squares solution directly. The deck writes "},{"type":"inlineCode","value":"w = (X\u1d40X)\u207b\xb9X\u1d40y"},{"type":"text","value":"; in the notebook the parameter vector includes both slope and intercept. The notebook uses "},{"type":"inlineCode","value":"np.linalg.solve"},{"type":"text","value":" rather than explicitly computing an inverse."}]},{"type":"paragraph","children":[{"type":"text","value":"Gradient descent instead repeatedly moves parameters opposite to the gradient: "},{"type":"inlineCode","value":"w \u2190 w \u2212 \u03b7 \u2202L/\u2202w"},{"type":"text","value":" and "},{"type":"inlineCode","value":"b \u2190 b \u2212 \u03b7 \u2202L/\u2202b"},{"type":"text","value":". The learning rate "},{"type":"inlineCode","value":"\u03b7"},{"type":"text","value":" sets the step size. For this linear least-squares problem, the loss is convex, which motivates the bowl analogy on slide 16."}]},{"type":"paragraph","children":[{"type":"strong","children":[{"type":"text","value":"Editorial qualifications:"}]},{"type":"text","value":" the inverse formula requires "},{"type":"inlineCode","value":"X\u1d40X"},{"type":"text","value":" to be invertible. The slide 18 surface is a generic non-convex illustration; it should not be taken as the shape of this linear least-squares loss. Claims on slide 18 about a single-step solution and scaling describe the two approaches broadly, rather than guaranteeing numerical stability or convergence for every dataset."}]},{"type":"paragraph","children":[{"type":"text","value":"Slide 17 credits its gradient-descent illustrations to "},{"type":"link","href":"https://www.geeksforgeeks.org/machine-learning/what-is-gradient-descent/","children":[{"type":"text","value":"GeeksforGeeks"}]},{"type":"text","value":" and "},{"type":"link","href":"https://medium.com/@datasciencewizards/a-simple-guide-to-gradient-descent-algorithm-60cbb66a0df9","children":[{"type":"text","value":"Data Science Wizards on Medium"}]},{"type":"text","value":". Those links are attributions supplied by the deck; their bodies are not imported here."}]}]},{"id":"section-10","heading":"When to stop (slide 19)","text":"The slide shows training cost decreasing and flattening over successive iterations, then asks where to stop. The notebook explores a loss-change tolerance, a maximum iteration count and several learning rates.","kind":"explanation","nodes":[{"type":"paragraph","children":[{"type":"text","value":"The slide shows training cost decreasing and flattening over successive iterations, then asks where to stop. The notebook explores a loss-change tolerance, a maximum iteration count and several learning rates."}]}]},{"id":"section-11","heading":"Notebook consistency note","text":"The supplied notebook defines half mean squared error, but its section 5 formula and code use twice the gradient of that loss. For `e = y - predict(x, w, b)`, the matching gradients are `dw = -np.mean(x * e)` and `db = -np.mean(e)`. The original implementation below uses `-(2 / n) * sum(...)`, equivalent to doubling the learning rate for the stated loss. Its code is preserved as supplied, with this correction made explicit rather than silently changing the exercise.\\n\\nAll notebook cells follow in their original order. Markdown headings and equation typography are normalised for this reading page, code is preserved, and exercise prompts are separate from solution code. The final supplied answer refers to a red curve in removed plot output; that colour-based claim has not been revalidated.","kind":"explanation","nodes":[{"type":"paragraph","children":[{"type":"text","value":"The supplied notebook defines half mean squared error, but its section 5 formula and code use twice the gradient of that loss. For "},{"type":"inlineCode","value":"e = y - predict(x, w, b)"},{"type":"text","value":", the matching gradients are "},{"type":"inlineCode","value":"dw = -np.mean(x * e)"},{"type":"text","value":" and "},{"type":"inlineCode","value":"db = -np.mean(e)"},{"type":"text","value":". The original implementation below uses "},{"type":"inlineCode","value":"-(2 / n) * sum(...)"},{"type":"text","value":", equivalent to doubling the learning rate for the stated loss. Its code is preserved as supplied, with this correction made explicit rather than silently changing the exercise."}]},{"type":"paragraph","children":[{"type":"text","value":"All notebook cells follow in their original order. Markdown headings and equation typography are normalised for this reading page, code is preserved, and exercise prompts are separate from solution code. The final supplied answer refers to a red curve in removed plot output; that colour-based claim has not been revalidated."}]}]},{"id":"section-12","heading":"Notebook overview (notebook cell 1)","text":"Source notebook title: \u201cSession 1: Linear Regression - Hands-on Exercises\u201d.","kind":"explanation","nodes":[{"type":"paragraph","children":[{"type":"text","value":"Source notebook title: \u201cSession 1: Linear Regression - Hands-on Exercises\u201d."}]}]},{"id":"section-13","heading":"Notebook setup (notebook cell 2)","text":"```python\\nimport numpy as np\\nimport matplotlib.pyplot as plt\\n\\nrng = np.random.default_rng(22)\\nplt.rcParams.update({\\"figure.figsize\\": (6, 4), \\"axes.grid\\": True, \\"grid.alpha\\": 0.3})\\n```","kind":"explanation","nodes":[{"type":"code","value":"import numpy as np\\nimport matplotlib.pyplot as plt\\n\\nrng = np.random.default_rng(22)\\nplt.rcParams.update({\\"figure.figsize\\": (6, 4), \\"axes.grid\\": True, \\"grid.alpha\\": 0.3})","language":"python"}]},{"id":"section-14","heading":"1. Generate data and split it (notebook cell 3)","text":"We create data from a known rule, `y = 2x + 1 + noise`, so we can check whether the model recovers it.\\nThen we split into a **train** set (fit the parameters) and a **test** set (judge the performance).","kind":"explanation","nodes":[{"type":"paragraph","children":[{"type":"text","value":"We create data from a known rule, "},{"type":"inlineCode","value":"y = 2x + 1 + noise"},{"type":"text","value":", so we can check whether the model recovers it.\\nThen we split into a "},{"type":"strong","children":[{"type":"text","value":"train"}]},{"type":"text","value":" set (fit the parameters) and a "},{"type":"strong","children":[{"type":"text","value":"test"}]},{"type":"text","value":" set (judge the performance)."}]}]},{"id":"section-15","heading":"Solution code (notebook cell 4)","text":"```python\\nn = 50\\nw_true, b_true = 2.0, 1.0\\n# choosing random x values between 0, 10\\nx = rng.uniform(0, 10, n)\\nprint(x)\\n# making the line\\ny = w_true * x + b_true + rng.normal(0, 1.5, n) # adding some noise (gotta make life annoying for ourselves)\\n# using the first 40 values as training, last 40-50 as the testing data \\nidx = rng.permutation(n)\\ntrain, test = idx[:40], idx[40:]\\nx_tr, y_tr = x[train], y[train]\\nx_te, y_te = x[test],  y[test]\\n\\n#plotting it\\nplt.scatter(x_tr, y_tr, label=\\"train\\")\\nplt.scatter(x_te, y_te, color=\\"orange\\", label=\\"test\\")\\nplt.xlabel(\\"Feature (x)\\"); plt.ylabel(\\"Target (y)\\"); plt.legend(); plt.show()\\n```","kind":"solution","nodes":[{"type":"code","value":"n = 50\\nw_true, b_true = 2.0, 1.0\\n# choosing random x values between 0, 10\\nx = rng.uniform(0, 10, n)\\nprint(x)\\n# making the line\\ny = w_true * x + b_true + rng.normal(0, 1.5, n) # adding some noise (gotta make life annoying for ourselves)\\n# using the first 40 values as training, last 40-50 as the testing data \\nidx = rng.permutation(n)\\ntrain, test = idx[:40], idx[40:]\\nx_tr, y_tr = x[train], y[train]\\nx_te, y_te = x[test],  y[test]\\n\\n#plotting it\\nplt.scatter(x_tr, y_tr, label=\\"train\\")\\nplt.scatter(x_te, y_te, color=\\"orange\\", label=\\"test\\")\\nplt.xlabel(\\"Feature (x)\\"); plt.ylabel(\\"Target (y)\\"); plt.legend(); plt.show()","language":"python"}]},{"id":"section-16","heading":"2. Predict a number: guess a line (notebook cell 5)","text":"The model is `\u0177 = wx + b`, where `w` is the slope and `b` is the baseline (intercept).\\n\\n**Exercise 2.** Change `w` and `b` below until the line looks like a good fit by eye.\\nTry the flat line `w = 0, b = 10` from the slides first.","kind":"explanation","nodes":[{"type":"paragraph","children":[{"type":"text","value":"The model is "},{"type":"inlineCode","value":"\u0177 = wx + b"},{"type":"text","value":", where "},{"type":"inlineCode","value":"w"},{"type":"text","value":" is the slope and "},{"type":"inlineCode","value":"b"},{"type":"text","value":" is the baseline (intercept)."}]},{"type":"paragraph","children":[{"type":"strong","children":[{"type":"text","value":"Exercise 2."}]},{"type":"text","value":" Change "},{"type":"inlineCode","value":"w"},{"type":"text","value":" and "},{"type":"inlineCode","value":"b"},{"type":"text","value":" below until the line looks like a good fit by eye.\\nTry the flat line "},{"type":"inlineCode","value":"w = 0, b = 10"},{"type":"text","value":" from the slides first."}]}]},{"id":"section-17","heading":"Solution code (notebook cell 6)","text":"```python\\ndef predict(x, w, b):\\n    return w*x + b\\n\\nw, b = 10, 10 # try change these around and find the best parameters by hand\\n\\nxs = np.linspace(0, 10, 100)\\nplt.scatter(x_tr, y_tr)\\nplt.plot(xs, predict(xs, w, b), \\"r\\")\\nplt.xlabel(\\"Feature (x)\\"); plt.ylabel(\\"Target (y)\\"); plt.title(f\\"w={w}, b={b}\\"); plt.show()\\n```","kind":"solution","nodes":[{"type":"code","value":"def predict(x, w, b):\\n    return w*x + b\\n\\nw, b = 10, 10 # try change these around and find the best parameters by hand\\n\\nxs = np.linspace(0, 10, 100)\\nplt.scatter(x_tr, y_tr)\\nplt.plot(xs, predict(xs, w, b), \\"r\\")\\nplt.xlabel(\\"Feature (x)\\"); plt.ylabel(\\"Target (y)\\"); plt.title(f\\"w={w}, b={b}\\"); plt.show()","language":"python"}]},{"id":"section-18","heading":"3. Least squares loss (notebook cell 7)","text":"The **residual** is the actual value minus the prediction: `e\u1d62 = y\u1d62 \u2212 \u0177\u1d62`.\\nSquaring stops positive and negative errors cancelling, and we average them:\\n\\n`L(w,b) = (1 / (2n)) \u03a3\u1d62\u208c\u2081\u207f (y\u1d62 \u2212 \u0177\u1d62)\xb2`","kind":"explanation","nodes":[{"type":"paragraph","children":[{"type":"text","value":"The "},{"type":"strong","children":[{"type":"text","value":"residual"}]},{"type":"text","value":" is the actual value minus the prediction: "},{"type":"inlineCode","value":"e\u1d62 = y\u1d62 \u2212 \u0177\u1d62"},{"type":"text","value":".\\nSquaring stops positive and negative errors cancelling, and we average them:"}]},{"type":"paragraph","children":[{"type":"inlineCode","value":"L(w,b) = (1 / (2n)) \u03a3\u1d62\u208c\u2081\u207f (y\u1d62 \u2212 \u0177\u1d62)\xb2"}]}]},{"id":"section-19","heading":"Solution code (notebook cell 8)","text":"```python\\ndef loss(w, b, x, y):\\n    residuals = y - predict(x,w,b)\\n    return np.mean(residuals ** 2) / 2\\n\\nfor (w_, b_) in [(0, 10), (1, 0), (2, 1), (3, 5)]:\\n    print(f\\"w={w_}, b={b_}:  loss = {loss(w_, b_, x_tr, y_tr):.2f}\\")\\n```","kind":"solution","nodes":[{"type":"code","value":"def loss(w, b, x, y):\\n    residuals = y - predict(x,w,b)\\n    return np.mean(residuals ** 2) / 2\\n\\nfor (w_, b_) in [(0, 10), (1, 0), (2, 1), (3, 5)]:\\n    print(f\\"w={w_}, b={b_}:  loss = {loss(w_, b_, x_tr, y_tr):.2f}\\")","language":"python"}]},{"id":"section-20","heading":"Exercise 3 (notebook cell 9)","text":"Which guess has the lowest loss? Does it match what you saw by eye in Section 2?\\n\\nNow look at the loss for *every* pair `(w,b)`. It forms a **bowl**, and the lowest point is the best line.","kind":"exercise","nodes":[{"type":"paragraph","children":[{"type":"text","value":"Which guess has the lowest loss? Does it match what you saw by eye in Section 2?"}]},{"type":"paragraph","children":[{"type":"text","value":"Now look at the loss for "},{"type":"emphasis","children":[{"type":"text","value":"every"}]},{"type":"text","value":" pair "},{"type":"inlineCode","value":"(w,b)"},{"type":"text","value":". It forms a "},{"type":"strong","children":[{"type":"text","value":"bowl"}]},{"type":"text","value":", and the lowest point is the best line."}]}]},{"id":"section-21","heading":"Solution code (notebook cell 10)","text":"```python\\nW, B = np.meshgrid(np.linspace(-1, 5, 200), np.linspace(-5, 8, 200))\\nZ = np.array([[loss(wi, bi, x_tr, y_tr) for wi in W[0]] for bi in B[:, 0]])\\n\\nplt.contourf(W, B, Z, levels=30, cmap=\\"viridis\\")\\nplt.colorbar(label=\\"Loss\\")\\nplt.xlabel(\\"w\\"); plt.ylabel(\\"b\\"); plt.title(\\"The loss is a bowl\\"); plt.show()\\n```","kind":"solution","nodes":[{"type":"code","value":"W, B = np.meshgrid(np.linspace(-1, 5, 200), np.linspace(-5, 8, 200))\\nZ = np.array([[loss(wi, bi, x_tr, y_tr) for wi in W[0]] for bi in B[:, 0]])\\n\\nplt.contourf(W, B, Z, levels=30, cmap=\\"viridis\\")\\nplt.colorbar(label=\\"Loss\\")\\nplt.xlabel(\\"w\\"); plt.ylabel(\\"b\\"); plt.title(\\"The loss is a bowl\\"); plt.show()","language":"python"}]},{"id":"section-22","heading":"4. Method 1: find the minimum directly (normal equations) (notebook cell 11)","text":"Set the gradient to zero. In matrix form, with `X` = a column of `x` values plus a column of ones:\\n\\n`\u2207w L = 0 \u21d2 w = (X\u1d40X)\u207b\xb9X\u1d40y`\\n\\nHere `w` holds both the slope and the intercept.","kind":"explanation","nodes":[{"type":"paragraph","children":[{"type":"text","value":"Set the gradient to zero. In matrix form, with "},{"type":"inlineCode","value":"X"},{"type":"text","value":" = a column of "},{"type":"inlineCode","value":"x"},{"type":"text","value":" values plus a column of ones:"}]},{"type":"paragraph","children":[{"type":"inlineCode","value":"\u2207w L = 0 \u21d2 w = (X\u1d40X)\u207b\xb9X\u1d40y"}]},{"type":"paragraph","children":[{"type":"text","value":"Here "},{"type":"inlineCode","value":"w"},{"type":"text","value":" holds both the slope and the intercept."}]}]},{"id":"section-23","heading":"Solution code (notebook cell 12)","text":"```python\\nX_tr = np.column_stack([x_tr, np.ones_like(x_tr)])\\n# linalg.solve solves for w in the form aw = b\\ntheta = np.linalg.solve(X_tr.T @ X_tr, X_tr.T @ y_tr)\\nw_ne, b_ne = theta\\nprint(f\\"Normal equations:  w = {w_ne:.4f}, b = {b_ne:.4f}   (truth: w=2, b=1)\\")\\n```","kind":"solution","nodes":[{"type":"code","value":"X_tr = np.column_stack([x_tr, np.ones_like(x_tr)])\\n# linalg.solve solves for w in the form aw = b\\ntheta = np.linalg.solve(X_tr.T @ X_tr, X_tr.T @ y_tr)\\nw_ne, b_ne = theta\\nprint(f\\"Normal equations:  w = {w_ne:.4f}, b = {b_ne:.4f}   (truth: w=2, b=1)\\")","language":"python"}]},{"id":"section-24","heading":"Exercise 4 (notebook cell 13)","text":"Re-run Sections 1 and 4 with `n = 10`, then `n = 500`. How close do `w` and `b` get to the truth, and why?","kind":"exercise","nodes":[{"type":"paragraph","children":[{"type":"text","value":"Re-run Sections 1 and 4 with "},{"type":"inlineCode","value":"n = 10"},{"type":"text","value":", then "},{"type":"inlineCode","value":"n = 500"},{"type":"text","value":". How close do "},{"type":"inlineCode","value":"w"},{"type":"text","value":" and "},{"type":"inlineCode","value":"b"},{"type":"text","value":" get to the truth, and why?"}]}]},{"id":"section-25","heading":"5. Method 2: gradient descent (notebook cell 14)","text":"Instead of solving in one step, repeatedly step downhill:\\n\\n`w \u2190 w \u2212 \u03b7 \u2202L/\u2202w`, `b \u2190 b \u2212 \u03b7 \u2202L/\u2202b`\\n\\nwith\\n\\n`\u2202L/\u2202w = \u2212(2/n) \u03a3 x\u1d62(y\u1d62 \u2212 \u0177\u1d62)`, `\u2202L/\u2202b = \u2212(2/n) \u03a3 (y\u1d62 \u2212 \u0177\u1d62)` (the supplied formula; see the consistency note above)\\n\\n`\u03b7` (eta) is the **learning rate**. We stop when the loss barely changes (`tol`) or after `max_iter` steps.","kind":"explanation","nodes":[{"type":"paragraph","children":[{"type":"text","value":"Instead of solving in one step, repeatedly step downhill:"}]},{"type":"paragraph","children":[{"type":"inlineCode","value":"w \u2190 w \u2212 \u03b7 \u2202L/\u2202w"},{"type":"text","value":", "},{"type":"inlineCode","value":"b \u2190 b \u2212 \u03b7 \u2202L/\u2202b"}]},{"type":"paragraph","children":[{"type":"text","value":"with"}]},{"type":"paragraph","children":[{"type":"inlineCode","value":"\u2202L/\u2202w = \u2212(2/n) \u03a3 x\u1d62(y\u1d62 \u2212 \u0177\u1d62)"},{"type":"text","value":", "},{"type":"inlineCode","value":"\u2202L/\u2202b = \u2212(2/n) \u03a3 (y\u1d62 \u2212 \u0177\u1d62)"},{"type":"text","value":" (the supplied formula; see the consistency note above)"}]},{"type":"paragraph","children":[{"type":"inlineCode","value":"\u03b7"},{"type":"text","value":" (eta) is the "},{"type":"strong","children":[{"type":"text","value":"learning rate"}]},{"type":"text","value":". We stop when the loss barely changes ("},{"type":"inlineCode","value":"tol"},{"type":"text","value":") or after "},{"type":"inlineCode","value":"max_iter"},{"type":"text","value":" steps."}]}]},{"id":"section-26","heading":"Solution code (notebook cell 15)","text":"```python\\ndef gradient_descent(x, y, eta=0.01, max_iter=5000, tol=1e-9, w0=0.0, b0=0.0):\\n    w, b = w0, b0\\n    n = len(x)\\n    history = [(w, b, loss(w, b, x, y))]\\n    for k in range(max_iter):\\n        e = y - predict(x, w, b)# residuals\\n        dw = -(2 / n) * np.sum(x * e)\\n        db = -(2 / n) * np.sum(e)\\n        w, b = w - eta * dw, b - eta * db      # step downhill\\n        history.append((w, b, loss(w, b, x, y)))\\n        if abs(history[-2][2] - history[-1][2]) < tol:   # cutoff: loss stopped improving\\n            break\\n    return w, b, np.array(history)\\n\\nw_gd, b_gd, hist = gradient_descent(x_tr, y_tr, eta=0.01)\\nprint(f\\"Stopped after {len(hist)-1} steps\\")\\nprint(f\\"Gradient descent:  w = {w_gd:.4f}, b = {b_gd:.4f}\\")\\nprint(f\\"Normal equations:  w = {w_ne:.4f}, b = {b_ne:.4f}\\")\\n```","kind":"solution","nodes":[{"type":"code","value":"def gradient_descent(x, y, eta=0.01, max_iter=5000, tol=1e-9, w0=0.0, b0=0.0):\\n    w, b = w0, b0\\n    n = len(x)\\n    history = [(w, b, loss(w, b, x, y))]\\n    for k in range(max_iter):\\n        e = y - predict(x, w, b)# residuals\\n        dw = -(2 / n) * np.sum(x * e)\\n        db = -(2 / n) * np.sum(e)\\n        w, b = w - eta * dw, b - eta * db      # step downhill\\n        history.append((w, b, loss(w, b, x, y)))\\n        if abs(history[-2][2] - history[-1][2]) < tol:   # cutoff: loss stopped improving\\n            break\\n    return w, b, np.array(history)\\n\\nw_gd, b_gd, hist = gradient_descent(x_tr, y_tr, eta=0.01)\\nprint(f\\"Stopped after {len(hist)-1} steps\\")\\nprint(f\\"Gradient descent:  w = {w_gd:.4f}, b = {b_gd:.4f}\\")\\nprint(f\\"Normal equations:  w = {w_ne:.4f}, b = {b_ne:.4f}\\")","language":"python"}]},{"id":"section-27","heading":"Exercise 5 (notebook cell 16)","text":"Change `tol` to `1e-3`, then `1e-12`. How many steps does it take each time, and how far from the normal-equation answer do you end up? This is the trade-off in choosing a cutoff: a loose cutoff stops early with a mostly right answer.","kind":"exercise","nodes":[{"type":"paragraph","children":[{"type":"text","value":"Change "},{"type":"inlineCode","value":"tol"},{"type":"text","value":" to "},{"type":"inlineCode","value":"1e-3"},{"type":"text","value":", then "},{"type":"inlineCode","value":"1e-12"},{"type":"text","value":". How many steps does it take each time, and how far from the normal-equation answer do you end up? This is the trade-off in choosing a cutoff: a loose cutoff stops early with a mostly right answer."}]}]},{"id":"section-28","heading":"6. The learning rate (notebook cell 17)","text":"Too small and it crawls; too large and it overshoots. Compare four values of `\u03b7`.","kind":"explanation","nodes":[{"type":"paragraph","children":[{"type":"text","value":"Too small and it crawls; too large and it overshoots. Compare four values of "},{"type":"inlineCode","value":"\u03b7"},{"type":"text","value":"."}]}]},{"id":"section-29","heading":"Solution code (notebook cell 18)","text":"```python\\nfig, ax = plt.subplots(figsize=(7, 4))\\nfor eta in [0.001, 0.01, 0.025, 0.035]:\\n    _, _, h = gradient_descent(x_tr, y_tr, eta=eta, max_iter=100, tol=0)\\n    ax.plot(h[:, 2], label=f\\"eta = {eta}\\")\\nax.set_yscale(\\"log\\"); ax.set_xlabel(\\"Iteration\\"); ax.set_ylabel(\\"Loss (log scale)\\")\\nax.legend(); plt.show()\\n```","kind":"solution","nodes":[{"type":"code","value":"fig, ax = plt.subplots(figsize=(7, 4))\\nfor eta in [0.001, 0.01, 0.025, 0.035]:\\n    _, _, h = gradient_descent(x_tr, y_tr, eta=eta, max_iter=100, tol=0)\\n    ax.plot(h[:, 2], label=f\\"eta = {eta}\\")\\nax.set_yscale(\\"log\\"); ax.set_xlabel(\\"Iteration\\"); ax.set_ylabel(\\"Loss (log scale)\\")\\nax.legend(); plt.show()","language":"python"}]},{"id":"section-30","heading":"Exercise 6 (notebook cell 19)","text":"Which values converge (work)?","kind":"exercise","nodes":[{"type":"paragraph","children":[{"type":"text","value":"Which values converge (work)?"}]}]},{"id":"section-31","heading":"Solution to Exercise 6 (notebook cell 19)","text":"Supplied answer: all but red (they settle at a low value whereas red increases with iterations)\\n\\nThis refers to the saved plot colours. The plots have been removed and this answer was not revalidated during publication.","kind":"solution","nodes":[{"type":"paragraph","children":[{"type":"text","value":"Supplied answer: all but red (they settle at a low value whereas red increases with iterations)"}]},{"type":"paragraph","children":[{"type":"text","value":"This refers to the saved plot colours. The plots have been removed and this answer was not revalidated during publication."}]}]}],"type":"tutorial","topics":["machine-learning","supervised-learning","linear-regression","least-squares","gradient-descent","numpy"],"series":"Machine Learning Tutorial Series","order":1,"archived":true,"origin":"curated","reviewedAt":"2026-10-29T23:48:56.000Z","source":{"url":"https://github.com/UCLAIS/UCLAIS.github.io/blob/24e06da03aa538cbc002767935da6d95d724ede8/knowledge/tutorials/machine-learning/session-1-intro-to-machine-learning.md","revision":"24e06da03aa538cbc002767935da6d95d724ede8","attribution":"UCL AI Society; supplied tutorial slides and notebook (authors not named in the slide text or notebook cells).","status":"approved"}},"releaseId":"053b96bc7dafd9857faf6870405f36aadd5a89849a66a0166422d24b4cc1d52c"}')}}]);